工厂方法和抽象工厂 工厂方法 定义一个创建对象的接口，让子类决定创建哪一个类。 代码如下：
#include &amp;lt;bits/stdc++.h&amp;gt; using namespace std; class Product { public: virtual ~Product() {} protected: Product() {} }; class concreteProductA : public Product { public: concreteProductA() { cout &amp;lt;&amp;lt; &amp;#34;create concreteProductA&amp;#34; &amp;lt;&amp;lt;endl; } virtual ~concreteProductA() {} }; class concreteProductB : public Product { public: concreteProductB() { cout &amp;lt;&amp;lt; &amp;#34;create concreteProductB&amp;#34; &amp;lt;&amp;lt;endl; } virtual ~concreteProductB() {} }; class Factory { public: Factory() {} virtual ~Factory() {} virtual Product* creatFactory() = 0; }; class createProductA : public Factory { public: Product* creatFactory() { return new concreteProductA; } }; class createProductB : public Factory { public: Product* creatFactory() { return new concreteProductB; } }; int main(int argc, char const *argv[]) { Factory* fac1 = new createProductA(); Factory* fac2 = new createProductB(); cout &amp;lt;&amp;lt; &amp;#34;**********&amp;#34; &amp;lt;&amp;lt; endl; Product* proA = fac1-&amp;gt;creatFactory(); Product* proB = fac2-&amp;gt;creatFactory(); return 0; } 工厂模式实现比较简单，但是工厂模式对于对象的创建仅仅局限于一个类（即Product是一个类），若要为不同的类实现对象创建的接口，需要使用抽象工厂模式
抽象工厂 结构图如下： 抽象工厂可以创建多个抽象产品类，比如说一个游戏种野怪有三种难度，共十个野怪，那么对于玩家开始游戏，就需要实例化三十个类创建野怪，这时候可以选择抽象工厂方式，将难度分为三种，解决一组相关或依赖的对象。 代码结构如下：
#include &amp;lt;bits/stdc++.h&amp;gt; using namespace std; //抽象产品A和B class ProductA { public: virtual ~ProductA() {} }; class ProductB { public: virtual ~ProductB() {} }; class concreteProductA1 : public ProductA{ public: concreteProductA1() { cout &amp;lt;&amp;lt; &amp;#34;create concreteProductA1&amp;#34; &amp;lt;&amp;lt;endl; } }; class concreteProductA2 : public ProductA { public: concreteProductA2() { cout &amp;lt;&amp;lt; &amp;#34;create concreteProductA2&amp;#34; &amp;lt;&amp;lt;endl; } }; class concreteProductB1 : public ProductB { public: concreteProductB1() { cout &amp;lt;&amp;lt; &amp;#34;create concreteProductB1&amp;#34; &amp;lt;&amp;lt;endl; } }; class concreteProductB2 : public ProductB { public: concreteProductB2() { cout &amp;lt;&amp;lt; &amp;#34;create concreteProductB2&amp;#34; &amp;lt;&amp;lt;endl; } }; //抽象工厂 class Factory { public: Factory() {} virtual ~Factory() {} virtual ProductA* creatFactoryA() = 0; virtual ProductB* creatFactoryB() = 0; }; //实例化工厂，生成类型1的产品 A1和B1 class createProduct1 : public Factory { public: ProductA* creatFactoryA() { return new concreteProductA1(); } ProductB* creatFactoryB() { return new concreteProductB1(); } }; //实例化工厂，生成类型2的产品 A2和B2 class createProduct2 : public Factory { public: ProductA* creatFactoryA() { return new concreteProductA2(); } ProductB* creatFactoryB() { return new concreteProductB2(); } }; int main(int argc, char const *argv[]) { Factory* fac1 = new createProduct1(); Factory* fac2 = new createProduct2(); ProductA* A1 = fac1 -&amp;gt; creatFactoryA(); ProductB* B1 = fac1 -&amp;gt; creatFactoryB(); ProductA* A2 = fac2 -&amp;gt; creatFactoryA(); ProductB* B2 = fac2 -&amp;gt; creatFactoryB(); return 0; } 可以把A、B想象成野怪，1、2想象成难度，如果玩家选择难度2，直接使用一个工厂createProduct2即可。
注意：一定要区分工厂方法和抽象工厂！！！

文章对应的题目 230 BST第K小的元素 538 二叉搜索树转化为累加树
二叉搜索树BST特性： 1、对于BST上每个节点node，左子树的节点的值都比node的值要小，右子树节点的值都比node的值要大。 2、对于BST的每一个节点node，他的左侧子树node -&amp;gt; left和右侧子树node -&amp;gt; right都为BST。 3、对BST做中序遍历，得到的遍历结果是升序的。
//对BST做中序遍历 void traverse(TreeNode* root) { if(root == nullptr) return; traverse(root -&amp;gt; left); cout &amp;lt;&amp;lt; root -&amp;gt; val &amp;lt;&amp;lt; endl; traverse(root -&amp;gt; right); return; } 230. 寻找第K小的元素 题目需求如上，直接思路就是中序遍历，找到排名第K的元素，代码如下。
/** * Definition for a binary tree node. * struct TreeNode { * int val; * TreeNode *left; * TreeNode *right; * TreeNode() : val(0), left(nullptr), right(nullptr) {} * TreeNode(int x) : val(x), left(nullptr), right(nullptr) {} * TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {} * }; */ class Solution { int res= 0; int i = 0; public: int kthSmallest(TreeNode* root, int k) { traverse(root, k); return res; } void traverse(TreeNode* root, int k) { if(root == nullptr) { return; } traverse(root -&amp;gt; left, k); i++; if(i == k) { res = root -&amp;gt; val; return; } traverse(root -&amp;gt; right, k); } }; 时间复杂度为O(N)，像红黑树这种自平衡的BST，增删查改时间复杂度都是对数级的O(logN)，所以说有点低效。 若要达到对数级的时间复杂度，就需要知道当前的节点的排名是多少（类似于二分查找）。 比如说你让我查找排名为k的元素，当前节点知道自己排名第m，那么我可以比较m和k的大小：
1、如果m == k，显然就是找到了第k个元素，返回当前节点就行了。 2、如果k &amp;lt; m，那说明排名第k的元素在左子树，所以可以去左子树搜索第k个元素。 3、如果k &amp;gt; m，那说明排名第k的元素在右子树，所以可以去右子树搜索第k - m - 1个元素。
这样就可以将时间复杂度降到O(logN)了。这就需要在二叉树节点中维护一个排名信息：
struct TreeNode { int val; //size为当前节点为根节点的树的节点总数 int size; TreeNode *left; TreeNode *right; TreeNode() : val(0), left(nullptr), right(nullptr) {} TreeNode(int x) : val(x), left(nullptr), right(nullptr) {} TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {} }; 这样就可以将排名k和node -&amp;gt; left -&amp;gt; size对比，达到对数级的时间复杂度。
二叉搜索树转化为累加树 其实就是利用二叉树的中序遍历特性，本题直接利用降序输出即可，递归顺序为：
void traverse(TreeNode* root) { if(root == nullprt) return; traverse(root -&amp;gt; right); cout &amp;lt;&amp;lt; root -&amp;gt; val &amp;lt;&amp;lt; endl; traverse(root -&amp;gt; left); } 这段代码可以从大到小降序打印 BST 节点的值，如果维护一个外部累加变量sum，然后把sum赋值给 BST 中的每一个节点，就可以将 BST 转化成累加树。代码如下：
/** * Definition for a binary tree node. * struct TreeNode { * int val; * TreeNode *left; * TreeNode *right; * TreeNode() : val(0), left(nullptr), right(nullptr) {} * TreeNode(int x) : val(x), left(nullptr), right(nullptr) {} * TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {} * }; */ class Solution { public: int sum = 0; TreeNode* convertBST(TreeNode* root) { GST(root); return root; } void GST(TreeNode* root) { if(root == nullptr) return; GST(root -&amp;gt; right); sum += root -&amp;gt; val; root -&amp;gt; val = sum; GST(root -&amp;gt; left); return; } }; [labuladong公众号](手把手刷二叉搜索树（第一期） (qq.com))
